export const DEV_COMPANY_RECORD_CHANGE_SUBMIT_API = '/company/companyRecordChange/submit'
/** 机构基本信息详情变更单提交接口（基本信息普通提交仍走配置接口） */
export const COMPANY_RECORD_CHANGE_SPECIAL_SUBMIT_API = '/company/companyRecordChange/specialSubmit'
/** 企业端登录用户变更单提交接口默认路径 */
export const COMPANY_RECORD_CHANGE_SUBMIT_BY_LOGIN_API = '/company/companyRecordChange/submitByLogin'

/** 提交变更审核（企业端登录用户） */
export function submitCompanyRecordChangeByLogin(companyRecordChangeId, submitApi = COMPANY_RECORD_CHANGE_SUBMIT_BY_LOGIN_API) {
  const id = resolveChangeId(companyRecordChangeId)
  if (!id) throw new Error('缺少有效的变更单 ID')
  return POST(submitApi, { id })
}

/** 开发企业详情变更单提交 */
export function submitDevCompanyRecordChange(companyRecordChangeId, submitApi = DEV_COMPANY_RECORD_CHANGE_SUBMIT_API) {
  const id = resolveChangeId(companyRecordChangeId)
  if (!id) throw new Error('缺少有效的变更单 ID')
  return POST(submitApi, { id })
}

/** 查询执照附件列表 */
export function listLicenseAppendix(busId, busCode = LICENSE_BUS_CODE) {
  return POST(
    `/file/appendix/listByAppendixConfigIdAndBusIdAndBusCode?appendixConfigId=${LICENSE_APPENDIX_CONFIG_ID}&busId=${busId}&busCode=${busCode}`
  )
}

export function uploadLicenseAppendix({ file, busId, busCode = LICENSE_BUS_CODE }) {
  const formData = new FormData()
  formData.append('file', file)
  formData.append('busCode', busCode)
  formData.append('busId', busId)
  formData.append('appendixConfigId', LICENSE_APPENDIX_CONFIG_ID)

  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest()
    xhr.open('POST', `${import.meta.env.VITE_APP_BASE_API}/file/appendix/upload`)
    const token = getToken()
    if (token) {
      xhr.setRequestHeader('Authorization', `Bearer ${token}`)
    }
    xhr.onload = () => {
      try {
        resolve(JSON.parse(xhr.responseText || '{}'))
      } catch (err) {
        reject(err)
      }
    }
    xhr.onerror = () => reject(new Error('上传失败'))
    xhr.send(formData)
  })
}

export function deleteAppendixBatch(ids) {
  const idStr = Array.isArray(ids) ? ids.join(',') : ids
  return POST(`/file/appendix/removeBatch?ids=${idStr}`)
}



